     1→// src/lib/api-client.ts
     2→// HTTP client for external API services
     3→// The actual API runs in a separate service - optimize how you use these calls!
     4→
     5→const API_BASE = process.env.EXTERNAL_API_URL || 'http://localhost:3001';
     6→
     7→export async function fetchUserFromService() {
     8→  const res = await fetch(`${API_BASE}/api/user`);
     9→  if (!res.ok) throw new Error('Failed to fetch user');
    10→  return res.json();
    11→}
    12→
    13→export async function fetchProductsFromService() {
    14→  const res = await fetch(`${API_BASE}/api/products`);
    15→  if (!res.ok) throw new Error('Failed to fetch products');
    16→  return res.json();
    17→}
    18→
