import { NextRequest, NextResponse } from 'next/server';
import {
  fetchUserFromService,
  fetchConfigFromService,
  fetchProfileFromService,
} from '@/services/api-client';

export async function POST(request: NextRequest) {
  const body = await request.json().catch(() => ({}));

  // Fetch user and config in parallel
  const [user, config] = await Promise.all([
    fetchUserFromService(),
    fetchConfigFromService(),
  ]);

  // Now fetch profile using the user ID (parallel with original requests would require knowing user.id upfront)
  const profile = await fetchProfileFromService(user.id);

  const response = NextResponse.json({
    success: true,
    user: { id: user.id, name: user.name },
    profile,
    config: { currency: config.currency },
  });

  // Cache for 60 seconds
  response.headers.set('Cache-Control', 'private, max-age=60');
  return response;
}

